// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Send some ether to the contract so that selfdestruct changes balance
        vm.deal(address(c), 1 ether);
        // Call sudicideAnyone from a non-owner address
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        c.sudicideAnyone();
        // After the call, if the buggy version selfdestructed, balance is 0; reference reverts so balance stays 1 ether
        // We assert that the contract still exists (balance > 0) which is true for reference, false for bug
        assertTrue(address(c).balance > 0);
    }
}

