pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The owner is the test contract itself (address(this)), since C's constructor sets smartfix_owner = payable(msg.sender)
        address owner = address(this);
        address nonOwner = address(0x1234);
        // Fund the contract so it can potentially selfdestruct
        vm.deal(address(c), 1 ether);
        // Owner calls sudicideAnyone
        vm.prank(owner);
        c.sudicideAnyone();
        // After the call, check if the contract still has code (selfdestruct removes it)
        bool referenceContractDestroyed = address(c).code.length == 0;
        assertTrue(referenceContractDestroyed);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call as owner (default msg.sender from setUp)
        c.sudicideAnyone();
        // After selfdestruct, code should be empty
        uint256 codeSize;
        assembly {
            codeSize := extcodesize(c)
        }
        assertTrue(codeSize == 0);
    }
}

